class Solution {
public:
    bool checkArray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<long long> d(n + 1, 0);
        long long cur = 0;
        for (int i = 0; i < n; i++) {
            cur -= d[i];
            long long need = (long long)nums[i] - cur;
            if (need < 0) return false;
            if (i + k > n) {
                if (need != 0) return false;
            } else {
                d[i + k] += need;
                cur += need;
            }
        }
        return true;
    }
};
